#include <iostream>
using namespace std;

using int64 = long long;
const int64 MOD = 1000000007;

int64 modPow(int64 base, int64 exp) {
    base %= MOD;
    int64 result = 1;
    while (exp > 0) {
        if (exp & 1) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, m, k;
    cin >> n >> m >> k;

    m %= MOD;

    if (k == 1 || k > n) {
        cout << modPow(m, n);
    } else if (k % 2 == 0) {
        cout << m;
    } else {
        cout << m * m % MOD;
    }

    return 0;
}

