#include <iostream>
using namespace std;

using ll = long long;

const int MOD = 1'000'000'007;

int modPow(ll base, int exp) {
    base %= MOD;
    ll result = 1;
    while (exp > 0) {
        if (exp & 1) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return static_cast<int>(result);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    cin >> n >> m >> k;

    int result;
    if (k == 1 || k > n) {
        result = modPow(m, n);
    } else if (k == n) {
        result = modPow(m, (n + 1) / 2);
    } else if (k % 2 == 0) {
        result = m % MOD;
    } else {
        result = static_cast<ll>(m % MOD) * (m % MOD) % MOD;
    }

    cout << result;
    return 0;
}

